function SubordinateMembers:ctor(parents,family_id,userId,owerId)

    local csbPath = "hall/res/FriendScircle/PartnerManagement/SubordinateMembers.csb"
    SubordinateMembers.super.ctor(self, csbPath)
    self.parents = parents
    self.userId = userId
    self.owerId = owerId
    self.family_id = family_id
    self.AllHeHuoRenList = {}
    self.sonPlayerCount = 0
    self.sonTempPlayCount = 0
    self:createTableView()
    self.item:hide()
    self.curPage = 1
	self.page_num = 8
	self.tatolPage = 1
    self:initEvent()
    self:InitGame()
    self:enableMask(true)
end

function SubordinateMembers:initEvent()
    ReqMgr:addHandle("SubordinateMembers", EVENTNAME)

    self.r_page:onClick(handler(self, self.btn_r_page))
	self.l_page:onClick(handler(self, self.btn_l_page))
end

--test
function SubordinateMembers:createTableView()
    self.userList = cc.TableView:create(cc.size(1117.03, 485))
    self.userList:setDirection(cc.SCROLLVIEW_DIRECTION_VERTICAL)
    self.userList:setVerticalFillOrder(cc.TABLEVIEW_FILL_TOPDOWN)
    self.userList:setAnchorPoint(cc.p(0, 0))
    self.userList:setPosition(cc.p(83.04, 101))
    self.userList:setDelegate()
    self.userList:addTo(self.root,99)
    self.userList:registerScriptHandler(handler(self, self.tableCellAtIndex), cc.TABLECELL_SIZE_AT_INDEX)
    self.userList:registerScriptHandler(handler(self, self.tableCellTouched), cc.TABLECELL_TOUCHED)
    self.userList:registerScriptHandler(self.cellSizeForTable, cc.TABLECELL_SIZE_FOR_INDEX)
    self.userList:registerScriptHandler(handler(self, self.numberOfCellsInTableView), cc.NUMBER_OF_CELLS_IN_TABLEVIEW)
    self.userList:reloadData()
end

--test
function SubordinateMembers:tableCellAtIndex(view, idx)
    local cell = view:dequeueCell()
    local item = nil
    if nil == cell then
        cell = cc.TableViewCell:new()
        local userBar = self:createUser(self.AllHeHuoRenList[idx+1], idx + 1)
        cell:addChild(userBar)
    else
        local node = cell:getChildByName("playerNode")
        self:initCellInfo(node,self.AllHeHuoRenList[idx+1], idx + 1)
    end
    return cell
end

function SubordinateMembers:initCellInfo(tempRoot,userItem,index)
    local userId = userItem.playerId or ""
    local xiaohaoYesterday = (userItem.xiaohaoYesterday or 0) / 100
    local gongxianYesterday = (userItem.gongxianYesterday or 0) / 100
	local teamPlayCountYesterday = userItem.teamPlayCountYesterday or 0
	local playCountYesterday = userItem.playCountYesterday or 0

    local playCountYesterday = userItem.playCountYesterday or 0
	local playCountToday = userItem.playCountToday or 0

	local dayingjiaCountYesterday = userItem.dayingjiaCountYesterday
	local pointCount = userItem.pointCount / 100
    local xiaohaoToday = (userItem.xiaohaoToday or 0) / 100
    local gongxianToday = (userItem.gongxianToday or 0) / 100
    xiaohaoToday = string.format("%0.2f", xiaohaoToday)
    xiaohaoYesterday = string.format("%0.2f", xiaohaoYesterday)
    gongxianToday = string.format("%0.2f", gongxianToday)
    gongxianYesterday = string.format("%0.2f", gongxianYesterday)
   
    tempRoot:getChildByName("partner_id"):setString(userId)
    tempRoot:getChildByName("fnt_bigwin"):setString(pointCount)--昨日大赢家
	tempRoot:getChildByName("fnt_gamenumber"):setString(playCountYesterday)--昨日团队局数
	tempRoot:getChildByName("fnt_gamenumber_me"):setString(playCountToday)--昨日个人局数
 	tempRoot:getChildByName("fnt_zuori_jifen"):setString(xiaohaoYesterday)--昨日积分
 	tempRoot:getChildByName("fnt_jinri_jifen"):setString(xiaohaoToday)--今日积分
 	tempRoot:getChildByName("fnt_zuori_gongxian"):setString(gongxianYesterday)--昨日贡献
    tempRoot:getChildByName("fnt_jinri_gongxian"):setString(gongxianToday)--今日贡献
    tempRoot.btn_rzxq.playerId = userItem.playerId
    tempRoot.btn_rzxq:onClick(handler(self, self.onClickLogInfo), true)

    local headportrait = tempRoot:getChildByName("headportrait")
    require("hall.GameCommon"):getUserHead(userItem.photo, "", "", headportrait, 54.94 , false, "", true)
end

