function SubordinateMembers:InitGame( page )
    -- body
    page = page or 1
    local data = {groupId = self.family_id , playerId = self.userId, currentPage = page, pageSize = self.page_num}
    dump(data,"我的玩家请求参数...")
    ReqMgr:request(EVENTNAME.SELECT_MEMBER_LIST_BY_DAYINGJIA, data, handler(self, self.FlushPartnerInfo), {page = page})
end

function SubordinateMembers:FlushPartnerInfo(event)
    if tolua.isnull(self) then
        return
    end
    local netData = event.netData
    local param = event.param
    local returnCode = netData.returnCode
    local data = netData.data
    local error = netData.error
    if not (returnCode == 0) then
        viewMgr:showTip({text = error})
        return
    end
    dump(netData,"我的玩家列表-----------------------------")

    self.AllHeHuoRenList = data.list
    self.sonPlayerCount = data.sonPlayerCount
    self.sonTempPlayCount = data.sonTempPlayCount

    self.tatolPage = math.ceil(data.listCount / self.page_num)
    if self.tatolPage == 0 then
        self.tatolPage = 1
    end
	self.curPage = param.page
    self.r_text:setString(self.curPage.."/"..self.tatolPage)
    self:FlushPartnerList_new(data)
    
end

function SubordinateMembers:btn_r_page()
	local page = self.curPage + 1
	if page <= 0 or page > self.tatolPage or self.curPage == page then
		return
	end
	self:InitGame(page)
end

function SubordinateMembers:btn_l_page()
	local page = self.curPage - 1
	if page <= 0 or page > self.tatolPage or self.curPage == page then
		return
	end
	self:InitGame(page)
end

function SubordinateMembers:setData()
	local data = nil
	local strNum = tonumber(USER_INFO["uid"])
    for k,v in pairs(self.AllHeHuoRenList) do
        if strNum == tonumber(v.playerId) then
            data = v
        end
    end
	
	if data then 
		self.txt_allXH:setString(data.teamPlayCountYesterday or 0)                -- 昨日开局总数
        -- self.txt_allXH:setString((self.sonPlayerCount or 0) .. "/" .. (self.sonTempPlayCount or 0))
		self.z_jifen:setString(data.xiaohaoYesterday / 100 or 0)                    -- 昨日积分消耗
	end
end

function SubordinateMembers:FlushPartnerList_new(data)
    if not data then return end
    self:setData()
    self.userList:reloadData()
end

